export interface ListAvailabilityTimeSlotConfigurationsRequest {
  /**
   * Deprecated. Use `services` instead.
   * @format GUID
   * @minSize 1
   * @maxSize 100
   * @deprecated
   */
  serviceIds?: string[];
  /**
   * Services to retrieve configurations for.
   *
   * This list is ordered. Return configurations in the same order as the services in this list.
   * The same service ID may appear multiple times with different customer choices.
   * @maxSize 100
   */
  services?: Service[];
}

/** Customer's selected choices during the booking flow. Use these values to calculate service configuration properties such as duration. */
export interface CustomerChoices {
  /**
   * Duration selected by the customer in minutes. Based on the customer's selection from [service options and variants](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/service-options-and-variants/introduction).
   * When using [add-ons](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/add-ons/introduction), we recommend passing only `addOnIds` instead of `durationInMinutes`. Wix Bookings then calculates the total duration automatically. If you specify both `addOnIds` and `durationInMinutes`, `durationInMinutes` must equal the service duration plus all selected add-on durations.
   * @min 1
   * @max 57600
   */
  durationInMinutes?: number | null;
  /**
   * IDs of [add-ons](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/add-ons/introduction) selected by the customer.
   * When specifying this field, we recommend omitting `durationInMinutes`. Wix Bookings then calculates the total duration based on the service duration plus all selected add-on durations.
   * @format GUID
   * @maxSize 21
   */
  addOnIds?: string[] | null;
  /**
   * ID of the duration choice selected by the customer.
   * @format GUID
   */
  durationChoiceId?: string | null;
  /**
   * Gender the customer narrowed an "any staff member" selection to.
   * Only time slots served by staff members of that gender are returned.
   * Omit to keep "any staff member" unnarrowed.
   *
   * Requires `genderPubliclyAccessible` to be enabled in the business's [staff member settings](https://dev.wix.com/docs/api-reference/business-solutions/bookings/staff-members/staff-member-settings/introduction). The call fails with `REQUESTED_GENDER_NOT_ALLOWED` when it's disabled.
   */
  requestedGender?: RequestedGenderValue;
}

/** Gender narrowing for an "any staff member" selection. */
export interface RequestedGenderValue {
  /** Gender the customer narrowed "any staff member" to. */
  gender?: RequestedGender;
}

/**
 * Selectable genders. Staff members of any other gender are reachable
 * through plain "any staff member" or by name.
 */
export enum RequestedGender {
  /**
   * Any male staff member.
   * @documentationMaturity preview
   */
  ANY_MALE = 'ANY_MALE',
  /**
   * Any female staff member.
   * @documentationMaturity preview
   */
  ANY_FEMALE = 'ANY_FEMALE',
}

export interface Service {
  /**
   * Service ID.
   * @format GUID
   */
  serviceId?: string;
  /** Customer's selected choices for this service, such as duration from [service options and variants](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/service-options-and-variants/introduction) or [add-ons](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/add-ons/introduction). */
  customerChoices?: CustomerChoices;
}

export interface ListAvailabilityTimeSlotConfigurationsResponse {
  /** Configurations for the requested services. Must contain one configuration per service in the request, in the same order. */
  configurations?: AvailabilityTimeSlotsConfiguration[];
}

export interface AvailabilityTimeSlotsConfiguration {
  /**
   * Service ID.
   * @format GUID
   */
  serviceId?: string;
  /**
   * [Resource types](https://dev.wix.com/docs/api-reference/business-solutions/bookings/resources/resource-types-v2/introduction) required to book this service. For example, a room from the "rooms" resource type and a staff member from the "staff" resource type.
   * @minSize 1
   * @maxSize 9
   */
  resourceTypes?: ResourceType[];
  /**
   * Locations where this service is offered.
   *
   * You can specify multiple `BUSINESS` locations, but only a single `CUSTOM` or `CUSTOMER` location.
   * @maxSize 100
   */
  locations?: Location[];
  /**
   * Time between available slots' start times in minutes. For example, with 5-minute intervals: `3:00`, `3:05`, and `3:10`.
   *
   * When the business configures the split interval to match the service duration, this value is the service duration
   * plus `bufferTimeInMinutes`. The maximum of `58320` therefore covers the longest bookable duration, 40 days
   * (`57600` minutes), plus the maximum `bufferTimeInMinutes` of `720`.
   * @min 1
   * @max 58320
   */
  splitIntervalInMinutes?: number;
  /** Service duration. Leave empty when `durationUnit.unitType` is `DAY`. */
  duration?: Duration;
  /**
   * Buffer time in minutes between the end of one slot and the start of the next.
   * @max 720
   */
  bufferTimeInMinutes?: number;
  /**
   * ID of the [schedule](https://dev.wix.com/docs/api-reference/business-management/calendar/schedules-v3/introduction) for this service.
   * @format GUID
   */
  scheduleId?: string | null;
  /**
   * Duration unit configuration for services that support a range of bookable durations.
   *
   * For hourly duration ranges, return both `duration` (with `defaultInMinutes` set to the minimum duration) and `durationUnit`.
   * For daily duration ranges, return only `durationUnit` with `unitType` set to `DAY` and leave `duration` empty.
   */
  durationUnit?: DurationUnit;
  /**
   * How the service's own working hours combine with its resources working hours when
   * computing availability. Leave unset for resource-based availability (the default). The
   * service's working hours are the `WORKING_HOURS` events on `scheduleId`; this field controls
   * only how they combine with the resources hours.
   * @internal
   */
  serviceWorkingHours?: ServiceWorkingHours;
}

export interface ResourceType {
  /**
   * Resource type ID.
   * @format GUID
   */
  resourceTypeId?: string | null;
  /**
   * IDs of resources available for booking within this resource type. These may be a subset of all resources in the type.
   * @format GUID
   * @maxSize 220
   */
  resourceIds?: string[] | null;
  /**
   * Number of resources required to book the service.
   *
   * Currently supports only a value of `1`.
   *
   * Default: `1`
   * @min 1
   * @max 1
   */
  numberOfResourcesRequired?: number | null;
  /**
   * Whether to return available resources in the response for this type.
   * @internal
   */
  returnAvailableResources?: boolean | null;
}

export interface Location {
  /**
   * Location ID. Returned only for business locations.
   * @format GUID
   */
  _id?: string | null;
  /** Location name. */
  name?: string | null;
  /** Full address of the location. */
  formattedAddress?: string | null;
  /** Location type. */
  locationType?: LocationType;
}

export enum LocationType {
  /** Custom location specific to this service, not defined as a business location. */
  CUSTOM = 'CUSTOM',
  /** Business location defined under Business Info in the dashboard. */
  BUSINESS = 'BUSINESS',
  /** Location determined by the customer at booking time. */
  CUSTOMER = 'CUSTOMER',
}

export interface Duration {
  /**
   * Default duration in minutes.
   * @min 1
   * @max 57600
   */
  defaultInMinutes?: number;
}

/**
 * Duration unit configuration for services with a range of bookable durations.
 * Defines the unit of time and the minimum and maximum durations a customer can select.
 */
export interface DurationUnit {
  /** Unit of time for the duration range. */
  unitType?: UnitType;
  /**
   * Minimum bookable duration. Value is in minutes when `unitType` is `HOUR`, and in days when `unitType` is `DAY`.
   * Must be less than or equal to `maxDuration`.
   *
   * For example, `60` for a 1-hour minimum or `1` for a 1-day minimum.
   * @min 1
   * @max 1440
   */
  minDuration?: number;
  /**
   * Maximum bookable duration. Value is in minutes when `unitType` is `HOUR`, and in days when `unitType` is `DAY`.
   * Must be greater than or equal to `minDuration`. Maximum for daily durations is 8 consecutive days.
   *
   * For example, `240` for a 4-hour maximum or `8` for an 8-day maximum.
   * @min 1
   * @max 1440
   */
  maxDuration?: number;
}

/** Unit of time for the duration range. */
export enum UnitType {
  /** Duration measured in hours. Availability is calculated as time slots. */
  HOUR = 'HOUR',
  /** Duration measured in days. Availability is calculated as full-day windows. */
  DAY = 'DAY',
}

/**
 * Controls how a service's own working hours combine with its resources working hours when
 * computing availability. The hours themselves are the `WORKING_HOURS` events on the
 * configuration's `scheduleId`; this message controls only how they combine with the
 * resources working hours.
 */
export interface ServiceWorkingHours {
  /** How the service's own working hours combine with its resources working hours. */
  mode?: Mode;
}

export enum Mode {
  /**
   * Bookable only where the service's own working hours and the resources working hours
   * overlap (the intersection of the two).
   * @documentationMaturity preview
   * @internal
   */
  INTERSECT_RESOURCE_HOURS = 'INTERSECT_RESOURCE_HOURS',
  /**
   * The service's own working hours replace the resources working-hours window. Existing
   * bookings and blocked time on those resources still reduce availability.
   * @documentationMaturity preview
   * @internal
   */
  OVERRIDE_RESOURCE_HOURS = 'OVERRIDE_RESOURCE_HOURS',
}

export interface AvailabilityTimeSlotsProviderConfig {
  /** Base URI where your service plugin endpoints are deployed. For example, `https://my-app.com`. */
  deploymentUri?: SpiBaseUri;
  /**
   * Display name for the provider.
   * @maxLength 100
   */
  providerName?: string | null;
}

/** Base URI configuration for a service plugin. Wix uses these URIs to call your service plugin methods. */
export interface SpiBaseUri {
  /**
   * Base URI for your service plugin. Wix appends each method's path to this URI.
   *
   * For example, to receive requests at `https://my-app.com/v1/my-method`, set this field to `https://my-app.com/`.
   * @minLength 6
   * @maxLength 2048
   */
  baseUri?: string;
  /** Alternative URIs for specific methods. Use these to override the default URI for individual methods. */
  alternativeUris?: AlternativeUri[];
}

/** Custom URI for the specified service plugin method. */
export interface AlternativeUri {
  /**
   * Name of the method to call at the absolute URI, in PascalCase. For example, to call [Get Shipping Rates](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/extensions/shipping-rates/shipping-rates-integration-service-plugin/get-shipping-rates) on an alternative URI, specify `GetShippingRates`.
   * @minLength 3
   * @maxLength 128
   */
  methodName?: string;
  /**
   * Absolute URI that Wix calls for this method. Wix doesn't append any path to this URI.
   *
   * The URI must begin with `https://`, such as `https://my-app.com/v1/my-custom-method`.
   * @minLength 6
   * @maxLength 2048
   */
  absoluteUri?: string;
}

/**
 * this message is not directly used by any service,
 * it exists to describe the expected parameters that SHOULD be provided to invoked Velo methods as part of open-platform.
 * e.g. SPIs, event-handlers, etc..
 * NOTE: this context object MUST be provided as the last argument in each Velo method signature.
 *
 * Example:
 * ```typescript
 * export function wixStores_onOrderCanceled({ event, metadata }: OrderCanceledEvent) {
 * ...
 * }
 * ```
 */
export interface Context {
  /** A unique identifier of the request. You may print this ID to your logs to help with future debugging and easier correlation with Wix's logs. */
  requestId?: string | null;
  /**
   * [ISO 4217](https://en.wikipedia.org/wiki/ISO_4217) 3-letter currency code.
   * @format CURRENCY
   */
  currency?: string | null;
  /** An object that describes the identity that triggered this request. */
  identity?: IdentificationData;
  /** A string representing a language and region in the format of `"xx-XX"`. First 2 letters represent the language code according to ISO 639-1. This is followed by a dash "-", and then a by 2 capital letters representing the region according to ISO 3166-2. For example, `"en-US"`. */
  languages?: string[];
  /**
   * The service provider app's instance ID.
   * @format GUID
   */
  instanceId?: string | null;
  /**
   * Extension ID in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionId?: string | null;
  /**
   * Extension type in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionType?: string | null;
  /**
   * Invoked function.
   * @internal
   * @maxLength 256
   */
  functionName?: string | null;
}

export enum IdentityType {
  UNKNOWN = 'UNKNOWN',
  ANONYMOUS_VISITOR = 'ANONYMOUS_VISITOR',
  MEMBER = 'MEMBER',
  WIX_USER = 'WIX_USER',
  APP = 'APP',
}

export interface IdentificationData extends IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
  /** @readonly */
  identityType?: IdentityType;
}

/** @oneof */
export interface IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
}
